package com.hmdp.ai.infrastructure.persistence;
import com.hmdp.ai.domain.tool.*;import com.hmdp.ai.infra.AiLogSanitizer;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.sql.Timestamp;import java.time.Instant;
@Repository public class JdbcToolAuditAdapter implements ToolAuditPort {private final JdbcTemplate jdbc;public JdbcToolAuditAdapter(JdbcTemplate jdbc){this.jdbc=jdbc;}@Override public void record(ToolDefinition d,ToolInvocation i,ToolResult r,long started,long duration){jdbc.update("insert into ai_tool_call (id,tenant_id,workspace_id,run_id,node_run_id,tool_id,tool_version,protocol,invocation_summary,result_summary,latency_ms,status,retryable,error_code,started_at,finished_at,created_by,updated_by) values (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",i.getCallId(),i.getContext().getTenantId(),i.getContext().getWorkspaceId(),i.getContext().getRunId(),i.getNodeRunId(),d.getId(),d.getVersion(),d.getProtocol().name(),AiLogSanitizer.safe(i.getInput().toString(),300),AiLogSanitizer.safe(r.getData()==null?r.getErrorMessage():r.getData().toString(),300),duration,r.getStatus().name(),r.isRetryable(),r.getErrorCode(),Timestamp.from(Instant.ofEpochMilli(started)),Timestamp.from(Instant.ofEpochMilli(started+duration)),i.getContext().getUserId(),i.getContext().getUserId());}}
